create type public.app_role as enum ('beneficiary','teacher','volunteer','admin');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, first_name text not null default '', last_name text not null default '', role app_role not null default 'beneficiary', created_at timestamptz not null default now());
create table public.memberships(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, status text not null check(status in ('pending','active','inactive','refunded')), amount_cents integer not null default 1000, activated_at timestamptz, unique(user_id));
create table public.courses(id uuid primary key default gen_random_uuid(), title text not null, language text not null check(language in ('fr','de')), level text not null, description text not null default '', teacher_id uuid references auth.users(id), published boolean not null default false, created_at timestamptz not null default now());
create table public.course_lessons(id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses(id) on delete cascade, title text not null, position integer not null, video_url text, duration_seconds integer);
create table public.live_sessions(id uuid primary key default gen_random_uuid(), course_id uuid references public.courses(id) on delete cascade, title text not null, start_at timestamptz not null, end_at timestamptz not null, meeting_url text, capacity integer not null default 20);
create table public.live_registrations(id uuid primary key default gen_random_uuid(), live_session_id uuid not null references public.live_sessions(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now(),unique(live_session_id,user_id));
create table public.lesson_progress(id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.course_lessons(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, percentage integer not null default 0 check(percentage between 0 and 100),completed_at timestamptz,unique(lesson_id,user_id));
create table public.support_requests(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, type text not null, subject text not null, description text not null, status text not null default 'submitted' check(status in ('submitted','assigned','in_progress','resolved','closed')),volunteer_id uuid references auth.users(id),created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.memberships enable row level security;alter table public.courses enable row level security;alter table public.course_lessons enable row level security;alter table public.live_sessions enable row level security;alter table public.live_registrations enable row level security;alter table public.lesson_progress enable row level security;alter table public.support_requests enable row level security;
create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "published courses" on public.courses for select using(published=true);create policy "own membership" on public.memberships for select using(auth.uid()=user_id);create policy "own live registrations" on public.live_registrations for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own progress" on public.lesson_progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own support requests" on public.support_requests for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
